// One new email per item, from the Gmail Trigger with Simplify off and Download Attachments on.
// Only attachment file names are read here. The files themselves are passed along untouched.
const m = $input.item.json;
const sender = (m.from && m.from.value && m.from.value[0]) || {};
const fromAddress = String(sender.address || '').trim();
const fromName = String(sender.name || '').trim();
const subject = String(m.subject || '').trim();
const body = String(m.text || '').replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim().slice(0, Number(m.max_email_chars) || 3000);
const attachments = Object.values($input.item.binary || {})
  .map((b) => `${b.fileName || 'unnamed'} (${b.mimeType || 'unknown type'})`);

const system = [
  'You sort incoming email for a small business.',
  'Decide if this email is an invoice, a receipt, or a bill: a document that asks for payment or confirms a payment was made.',
  'Count these: invoices, receipts, order confirmations that show an amount paid, utility and phone bills,',
  'subscription renewal charges, and reminders about an unpaid invoice.',
  'Do not count these: quotes and estimates, newsletters, marketing, shipping updates with no amount,',
  'password and login emails, and ordinary conversation.',
  'Answer with JSON only, in this shape:',
  '{"is_invoice": true, "kind": "invoice", "vendor": "who sent it", "reason": "one short sentence"}',
  'kind must be one of: invoice, receipt, bill, reminder, none.',
].join('\n');

const user = [
  `FROM: ${fromName ? fromName + ' <' + fromAddress + '>' : fromAddress}`,
  `SUBJECT: ${subject}`,
  `ATTACHMENTS: ${attachments.length ? attachments.join(', ') : 'none'}`,
  '',
  body || '(no text body)',
].join('\n');

return {
  json: {
    message_id: m.id || '',
    from: fromAddress,
    subject,
    attachments,
    ollama_request: {
      url: String(m.ollama_url || 'http://localhost:11434').replace(/\/+$/, '') + '/api/chat',
      body: {
        model: m.ollama_model || 'qwen2.5:3b',
        stream: false,
        format: 'json',
        options: { temperature: 0 },
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
      },
    },
  },
  binary: $input.item.binary,
};

// Ollama's /api/chat answer is in message.content. With format: "json" it should be a JSON string,
// but a small model sometimes wraps it in text, so take the first {...} block if a plain parse fails.
function readModelJson(res) {
  const raw = String((res && res.message && res.message.content) || res.response || '').trim();
  if (!raw) return { ok: false, raw, data: {} };
  try { return { ok: true, raw, data: JSON.parse(raw) }; } catch (e) {}
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { return { ok: true, raw, data: JSON.parse(m[0]) }; } catch (e) {} }
  return { ok: false, raw, data: {} };
}

const src = $('Check Email And Build Prompt').item;
const e = src.json;
const parsed = readModelJson($input.item.json);
const kinds = ['invoice', 'receipt', 'bill', 'reminder'];
const kind = String(parsed.data.kind || 'none').toLowerCase().trim();
// Both fields must agree before a label goes on. A wrong label is worse than a missed one here.
const isInvoice = parsed.data.is_invoice === true && kinds.includes(kind);

return {
  json: {
    is_invoice: isInvoice,
    kind: isInvoice ? kind : 'none',
    vendor: String(parsed.data.vendor || '').trim(),
    reason: String(parsed.data.reason || (parsed.ok ? '' : 'the model answer could not be read')).trim(),
    message_id: e.message_id,
    from: e.from,
    subject: e.subject,
    attachments: e.attachments,
  },
  binary: src.binary,
};
